{
  "category_edits": [
    {
      "category": "learning_objective",
      "rationale": "Test pairwise softplus ranking loss plus 0.2-weighted pointwise logistic supervision to constrain score drift on the unit-normalized incumbent. Apply across all four datasets, preserving nonpadding averaging, sampling, model architecture, inference, optimizer and training settings.",
      "edits": [
        {
          "find": "    loss = -torch.log(torch.sigmoid(pos_scores - neg_scores) + 1e-8)\n    return (loss * mask).sum() / mask.sum().clamp(min=1.0)",
          "replace": "    pairwise_loss = torch.nn.functional.softplus(neg_scores - pos_scores)\n    pointwise_loss = (\n        torch.nn.functional.softplus(-pos_scores)\n        + torch.nn.functional.softplus(neg_scores)\n    )\n    loss = pairwise_loss + 0.2 * pointwise_loss\n    return (loss * mask).sum() / mask.sum().clamp(min=1.0)"
        }
      ]
    }
  ],
  "change_summary": "Replace BPR with stable pairwise softplus plus 0.2-weighted pointwise logistic loss. Predictor and checkpoint shapes remain unchanged."
}
